+func (p Plan) ChangedFields(previous Plan) []string {
+	currentValue, previousValue := reflect.ValueOf(p), reflect.ValueOf(previous)
+	typeOfPlan := currentValue.Type()
+	var fields []string
+	for index := 0; index < currentValue.NumField(); index++ {
